@import url('https://fonts.googleapis.com/css2?family=DM+Sans:wght@400;500;700&family=Space+Grotesk:wght@500;600;700&display=swap');

:root { --ink:#17233c; --muted:#71809b; --line:#e5eaf3; --accent:#635bff; --soft:#f5f6ff; }
* { box-sizing:border-box; }
body { margin:0; min-height:100vh; color:var(--ink); background:#f1f4fa; font-family:'DM Sans', sans-serif; }
.app-shell { width:min(820px, calc(100% - 32px)); margin:0 auto; padding:58px 0 36px; }
.hero { text-align:center; margin-bottom:34px; }
.eyebrow { color:var(--accent); font-size:11px; font-weight:700; letter-spacing:2px; margin-bottom:14px; }
h1 { font-family:'Space Grotesk', sans-serif; font-size:clamp(32px, 6vw, 49px); letter-spacing:-2px; margin:0 0 12px; }
.hero p { color:var(--muted); margin:0; font-size:16px; }
.quiz-card { background:#fff; border:1px solid #e8ecf4; border-radius:24px; padding:12px 34px 28px; box-shadow:0 18px 55px rgba(41,54,88,.08); }
.question { padding:27px 0 30px; border-bottom:1px solid var(--line); }
.question-heading { display:flex; align-items:flex-start; gap:15px; }
.question-number { color:var(--accent); background:var(--soft); border-radius:8px; padding:6px 8px; font-size:12px; font-weight:700; letter-spacing:.5px; }
h2 { font-family:'Space Grotesk', sans-serif; font-size:19px; line-height:1.35; margin:3px 0 20px; }
.options { display:grid; grid-template-columns:repeat(3,1fr); gap:11px; margin-left:47px; }
.option { position:relative; display:flex; align-items:center; gap:10px; min-height:48px; padding:12px 14px; border:1px solid var(--line); border-radius:11px; color:#4d5b75; font-size:14px; cursor:pointer; transition:.2s ease; }
.option:hover { border-color:#a9a5ff; background:#fafaff; }
.option:has(input:checked) { border-color:var(--accent); background:var(--soft); color:var(--ink); font-weight:500; box-shadow:0 0 0 2px rgba(99,91,255,.1); }
.option input { position:absolute; opacity:0; pointer-events:none; }
.custom-radio { width:16px; height:16px; border:1.5px solid #b9c1d1; border-radius:50%; flex:none; }
.option:has(input:checked) .custom-radio { border:5px solid var(--accent); }
.quiz-footer { display:flex; align-items:center; justify-content:space-between; gap:20px; padding-top:25px; }
.feedback { color:#d44d63; font-size:13px; min-height:20px; margin:0; }
button { border:0; border-radius:11px; background:var(--accent); color:#fff; padding:14px 21px; font-family:inherit; font-weight:700; cursor:pointer; box-shadow:0 8px 18px rgba(99,91,255,.22); transition:transform .2s, background .2s; }
button:hover { background:#5048eb; transform:translateY(-1px); }
button span { font-size:18px; margin-left:8px; }
.result { display:none; align-items:baseline; justify-content:center; gap:8px; margin-top:24px; padding:18px; border-radius:14px; background:#f2fbf7; color:#197052; }
.result.visible { display:flex; }
.result-label { font-size:14px; font-weight:500; }
.result strong { font-family:'Space Grotesk',sans-serif; font-size:34px; }
.result-total { font-size:16px; color:#629783; }
.footer-note { color:#9aa6bb; text-align:center; font-size:12px; margin-top:22px; }
@media (max-width:650px) { .app-shell { padding-top:35px; } .quiz-card { padding:8px 18px 22px; } .options { grid-template-columns:1fr; margin-left:0; } h2 { font-size:17px; } .quiz-footer { align-items:stretch; flex-direction:column; } button { width:100%; } }

