const form = document.getElementById('quiz-form');
const feedback = document.getElementById('feedback');
const result = document.querySelector('.result');
const scoreElement = document.querySelector('[data-testid="quiz-score"]');
const answers = { q1: 'mars', q2: 'pacific', q3: 'six' };

form.addEventListener('submit', (event) => {
  event.preventDefault();
  const formData = new FormData(form);
  const unanswered = Object.keys(answers).filter((question) => !formData.get(question));
  if (unanswered.length) {
    feedback.textContent = 'Please answer all three questions first.';
    result.classList.remove('visible');
    scoreElement.removeAttribute('data-score');
    scoreElement.textContent = '';
    const firstMissing = form.querySelector(`input[name="${unanswered[0]}"]`);
    if (firstMissing) firstMissing.focus();
    return;
  }

  let score = 0;
  Object.entries(answers).forEach(([question, answer]) => {
    if (formData.get(question) === answer) score += 1;
  });
  feedback.textContent = '';
  scoreElement.textContent = String(score);
  scoreElement.setAttribute('data-score', String(score));
  result.classList.add('visible');
});

